/**
 * The generated list of language files (docs/SCREENS.md §0.1: "adding a language = adding a file").
 * The app runs where there is no file system (Cloudflare Workers), so the files are found at BUILD
 * time: `pnpm --filter @retail/i18n generate` lists `messages/*.json` and writes a module that
 * imports each one. `check` fails CI if that module is out of date.
 */
export function renderRegistry(codes: readonly string[]): string {
  const sorted = [...codes].sort();
  const name = (code: string) => `messages_${code.replace(/[^A-Za-z0-9]/g, "_")}`;
  return [
    "// GENERATED by packages/i18n/scripts/generate.ts from messages/*.json. Do not edit by hand:",
    "// add or remove a file in messages/ and run `pnpm --filter @retail/i18n generate`.",
    ...sorted.map((code) => `import ${name(code)} from "../../messages/${code}.json";`),
    "",
    "export const MESSAGES: Record<string, unknown> = {",
    ...sorted.map((code) => `  ${JSON.stringify(code)}: ${name(code)},`),
    "};",
    "",
  ].join("\n");
}
